#include <Servo.h>

Servo myServo;

const int SERVO_PIN = 9;      // Пин, куда подключён сервопривод
const int PWM_INPUT_PIN = 5;  // Пин, куда подключён PWM_5 с платы

void setup() {
  myServo.attach(SERVO_PIN);
  pinMode(PWM_INPUT_PIN, INPUT);
  Serial.begin(9600);
}

void loop() {
  // Читаем длительность импульса с выхода PWM_5
  // Стандартный RC-сигнал: 1000–2000 мкс
  int pulseWidth = pulseIn(PWM_INPUT_PIN, HIGH, 25000);

  // Защита от потери сигнала (если импульса нет, pulseIn вернёт 0)
  if (pulseWidth == 0) {
    return;
  }

  // Преобразуем 1000–2000 мкс в угол 0–180°
  int angle = map(pulseWidth, 1000, 2000, 0, 180);

  // Ограничиваем диапазон на случай шумов
  angle = constrain(angle, 0, 180);

  myServo.write(angle);

  Serial.print("Pulse: ");
  Serial.print(pulseWidth);
  Serial.print(" | Angle: ");
  Serial.println(angle);

  delay(20);
}
